```tsx
// TooltipContext.tsx
import React, { createContext, useContext, useState, ReactNode } from 'react';

interface TooltipContextType {
  activeTooltip: string | null;
  setActiveTooltip: (tooltipId: string | null) => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeTooltip, setActiveTooltip] = useState<string | null>(null);

  return (
    <TooltipContext.Provider value={{ activeTooltip, setActiveTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = (): TooltipContextType => {
  const context = useContext(TooltipContext);
  if (context === undefined) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

